<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin-auth' })

type ArticleStatus = 'DRAFT' | 'PUBLISHED' | 'ARCHIVED'
type ArticleBlock = { type: 'paragraph' | 'heading' | 'image' | 'blockquote' | 'list' | 'callout'; level?: 2 | 3; text?: string; ordered?: boolean; items?: string[]; src?: string; alt?: string; caption?: string }
type AdminArticle = { id: number; title: string; slug: string; excerpt: string; heroImage: string; heroImageAlt: string; body: ArticleBlock[]; city: string; contentType: string; category: string; tags: string[]; status: ArticleStatus; priority: number; publishedAt: string | null; createdAt: string; updatedAt: string }

const articles = ref<AdminArticle[]>([])
const pending = ref(false)
const error = ref('')
const notice = ref('')
const search = ref('')
const statusFilter = ref('')
const cityFilter = ref('')
const categoryFilter = ref('')
const editingId = ref<number | null>(null)
const previewOpen = ref(false)
const slugTouched = ref(false)
const form = reactive({ title: '', slug: '', excerpt: '', heroImage: '', heroImageAlt: '', city: 'GENERAL', contentType: 'article', category: 'Kehidupan', tags: '', status: 'DRAFT' as ArticleStatus, priority: 0, body: [] as ArticleBlock[] })

const categories = computed(() => [...new Set(articles.value.map((article) => article.category).filter(Boolean))].sort())
const editingArticle = computed(() => editingId.value ? articles.value.find((article) => article.id === editingId.value) ?? null : null)

function slugify(value: string) { return value.toLocaleLowerCase().trim().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 180) }
function formatDate(value: string | null) { return value ? new Date(value).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : '—' }
function formatUpdated(value: string) { return new Date(value).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) }
function emptyForm() { editingId.value = null; slugTouched.value = false; Object.assign(form, { title: '', slug: '', excerpt: '', heroImage: '', heroImageAlt: '', city: 'GENERAL', contentType: 'article', category: 'Kehidupan', tags: '', status: 'DRAFT', priority: 0, body: [{ type: 'paragraph', text: '' }] }); previewOpen.value = false }
function editArticle(article: AdminArticle) { editingId.value = article.id; slugTouched.value = true; Object.assign(form, { title: article.title, slug: article.slug, excerpt: article.excerpt, heroImage: article.heroImage, heroImageAlt: article.heroImageAlt, city: article.city, contentType: article.contentType, category: article.category, tags: article.tags.join(', '), status: article.status, priority: article.priority, body: JSON.parse(JSON.stringify(article.body ?? [])) }); previewOpen.value = false; window.scrollTo({ top: 0, behavior: 'smooth' }) }
function addBlock(type: ArticleBlock['type']) { form.body.push(type === 'heading' ? { type, level: 2, text: '' } : type === 'list' ? { type, ordered: false, items: [''] } : type === 'image' ? { type, src: '', alt: '', caption: '' } : { type, text: '' }) }
function removeBlock(index: number) { form.body.splice(index, 1) }
function normalizeBlock(block: ArticleBlock): ArticleBlock { if (block.type === 'list') return { ...block, items: (block.items ?? []).filter(Boolean) }; return block }
function datePayload() { return form.status === 'PUBLISHED' ? new Date().toISOString() : null }
function payload() { return { title: form.title.trim(), slug: form.slug.trim(), excerpt: form.excerpt.trim(), heroImage: form.heroImage.trim(), heroImageAlt: form.heroImageAlt.trim(), body: form.body.map(normalizeBlock), city: form.city, contentType: form.contentType, category: form.category.trim(), tags: form.tags.split(',').map((tag) => tag.trim().toLocaleLowerCase()).filter(Boolean), status: form.status, priority: Number(form.priority) || 0, publishedAt: datePayload(), seoTitle: null, seoDescription: null, ogImage: null } }
async function loadArticles() { pending.value = true; error.value = ''; try { const response = await $fetch<{ data: AdminArticle[] }>('/api/admin/media/articles', { query: { search: search.value || undefined, status: statusFilter.value || undefined, city: cityFilter.value || undefined, category: categoryFilter.value || undefined } }); articles.value = response.data } catch (err: unknown) { error.value = (err as { data?: { statusMessage?: string } }).data?.statusMessage ?? 'Artikel gagal dimuat.' } finally { pending.value = false } }
async function saveArticle(status: ArticleStatus = form.status) { error.value = ''; notice.value = ''; form.status = status; try { const body = payload(); if (!body.title || !body.slug || !body.category) throw new Error('Judul, slug, dan kategori wajib diisi.'); if (editingId.value) { await $fetch(`/api/admin/media/articles/${editingId.value}`, { method: 'PATCH', body }) } else { const response = await $fetch<{ data: AdminArticle }>('/api/admin/media/articles', { method: 'POST', body }); editingId.value = response.data.id; slugTouched.value = true } notice.value = status === 'PUBLISHED' ? 'Artikel berhasil diterbitkan.' : status === 'ARCHIVED' ? 'Artikel diarsipkan.' : 'Draft tersimpan.'; await loadArticles() } catch (err: unknown) { error.value = err instanceof Error ? err.message : (err as { data?: { statusMessage?: string } }).data?.statusMessage ?? 'Artikel gagal disimpan.' } }
async function setStatus(status: ArticleStatus) { if (!editingId.value) return saveArticle(status); await saveArticle(status) }
watch(() => form.title, (title) => { if (!slugTouched.value) form.slug = slugify(title) })
watch([search, statusFilter, cityFilter, categoryFilter], loadArticles)
onMounted(loadArticles)
</script>

<template>
  <div>
    <PageHead title="Artikel" subtitle="Media · Content Library"><template #actions><button type="button" class="rounded-full bg-brand-green px-4 py-2 text-sm font-semibold text-white hover:bg-[#0b3230]" @click="emptyForm">Artikel Baru</button></template></PageHead>
    <div v-if="error" class="mt-4 rounded-xl border border-gold-soft bg-gold-sand/50 px-4 py-3 text-sm" role="alert">{{ error }}</div>
    <div v-if="notice" class="mt-4 rounded-xl border border-brand-green/20 bg-brand-green/5 px-4 py-3 text-sm text-brand-green" role="status">{{ notice }}</div>

    <section class="mt-6 rounded-2xl border border-neutral-line bg-white p-5" aria-label="Filter artikel">
      <div class="grid gap-3 md:grid-cols-4"><label class="md:col-span-2"><span class="text-xs font-semibold uppercase tracking-[0.12em] text-neutral-charcoal/50">Cari</span><input v-model="search" type="search" placeholder="Cari judul atau slug..." class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm focus:border-brand-green focus:outline-none focus:ring-2 focus:ring-brand-green/15" /></label><label><span class="text-xs font-semibold uppercase tracking-[0.12em] text-neutral-charcoal/50">Status</span><select v-model="statusFilter" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm"><option value="">Semua status</option><option>DRAFT</option><option>PUBLISHED</option><option>ARCHIVED</option></select></label><label><span class="text-xs font-semibold uppercase tracking-[0.12em] text-neutral-charcoal/50">City</span><select v-model="cityFilter" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm"><option value="">Semua city</option><option>GENERAL</option><option>MAKKAH</option><option>MADINAH</option></select></label></div>
      <label v-if="categories.length" class="mt-3 block max-w-sm"><span class="text-xs font-semibold uppercase tracking-[0.12em] text-neutral-charcoal/50">Kategori</span><select v-model="categoryFilter" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm"><option value="">Semua kategori</option><option v-for="category in categories" :key="category">{{ category }}</option></select></label>
    </section>

    <div class="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1fr)_minmax(360px,0.8fr)]">
      <section class="rounded-2xl border border-neutral-line bg-white p-5" aria-labelledby="article-list-heading"><div class="flex items-center justify-between"><h2 id="article-list-heading" class="font-heading text-lg font-semibold">Daftar Artikel</h2><span class="text-xs text-neutral-charcoal/50">{{ articles.length }} artikel</span></div><div v-if="pending" class="py-12 text-center text-sm text-neutral-charcoal/50">Memuat artikel...</div><div v-else-if="!articles.length" class="border-t border-neutral-line py-12 text-center text-sm text-neutral-charcoal/55">Belum ada artikel.</div><div v-else class="mt-4 divide-y divide-neutral-line"><button v-for="article in articles" :key="article.id" type="button" class="flex w-full items-start justify-between gap-4 py-4 text-left hover:bg-neutral-soft/50" @click="editArticle(article)"><span class="min-w-0"><span class="block truncate font-semibold text-neutral-charcoal">{{ article.title }}</span><span class="mt-1 block text-xs text-neutral-charcoal/55">{{ article.city }} · {{ article.category }} · Prioritas {{ article.priority }}</span><span class="mt-1 block text-xs text-neutral-charcoal/45">Terbit: {{ formatDate(article.publishedAt) }} · Diubah: {{ formatUpdated(article.updatedAt) }}</span></span><span class="shrink-0 rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.1em]" :class="article.status === 'PUBLISHED' ? 'bg-brand-green/10 text-brand-green' : article.status === 'ARCHIVED' ? 'bg-neutral-line text-neutral-charcoal/55' : 'bg-gold-sand text-neutral-charcoal/70'">{{ article.status }}</span></button></div></section>

      <section class="rounded-2xl border border-neutral-line bg-white p-5" aria-labelledby="article-editor-heading"><div class="flex items-center justify-between gap-3"><h2 id="article-editor-heading" class="font-heading text-lg font-semibold">{{ editingArticle ? 'Edit Artikel' : 'Artikel Baru' }}</h2><button v-if="editingId" type="button" class="text-xs font-semibold text-neutral-charcoal/55 underline underline-offset-4" @click="emptyForm">Reset</button></div><div class="mt-5 space-y-4"><label class="block text-sm font-semibold">Judul<input v-model="form.title" type="text" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal" placeholder="Judul artikel" /></label><label class="block text-sm font-semibold">Slug<input v-model="form.slug" type="text" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal" @input="slugTouched = true" /></label><label class="block text-sm font-semibold">Excerpt<p class="mt-1 text-xs font-normal text-neutral-charcoal/55">Ringkasan singkat yang digunakan pada kartu artikel dan preview.</p><textarea v-model="form.excerpt" rows="3" class="mt-1.5 w-full rounded-xl border border-neutral-line px-3 py-2 text-sm font-normal" /></label><div class="grid gap-3 sm:grid-cols-2"><label class="block text-sm font-semibold">City<select v-model="form.city" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal"><option>GENERAL</option><option>MAKKAH</option><option>MADINAH</option></select></label><label class="block text-sm font-semibold">Content Type<select v-model="form.contentType" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal"><option value="article">Artikel</option><option value="update">Update</option><option value="practical">Panduan Praktis</option></select></label></div><div class="grid gap-3 sm:grid-cols-[1fr_100px]"><label class="block text-sm font-semibold">Kategori<select v-model="form.category" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal"><option v-for="category in ['Kehidupan', 'Panduan', 'Transportasi', 'Masjid', 'Makkah', 'Madinah']" :key="category">{{ category }}</option></select></label><label class="block text-sm font-semibold">Prioritas<input v-model.number="form.priority" type="number" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal" /></label></div><label class="block text-sm font-semibold">Tags<span class="font-normal text-neutral-charcoal/50"> (pisahkan dengan koma)</span><input v-model="form.tags" type="text" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal" placeholder="makkah, panduan" /></label><div class="grid gap-3 sm:grid-cols-2"><MediaImageUploader v-model="form.heroImage" label="Hero Image" folder="articles" /><label class="block text-sm font-semibold">Hero Image Alt<input v-model="form.heroImageAlt" type="text" class="mt-1.5 min-h-[42px] w-full rounded-xl border border-neutral-line px-3 text-sm font-normal" /></label></div>

        <div class="border-t border-neutral-line pt-4"><div class="flex items-center justify-between"><div><h3 class="font-semibold">Body Blocks</h3><p class="mt-1 text-xs text-neutral-charcoal/55">Structured JSON blocks, bukan raw HTML.</p></div><select class="min-h-[36px] rounded-full border border-neutral-line px-3 text-xs" @change="(event) => { const select = event.target as HTMLSelectElement; if (select.value) addBlock(select.value as ArticleBlock['type']); select.value = '' }"><option value="">Tambah block...</option><option value="paragraph">Paragraph</option><option value="heading">H2 / H3</option><option value="image">Image</option><option value="blockquote">Quote</option><option value="list">Bullet / Numbered List</option><option value="callout">Info / Callout</option></select></div><div class="mt-4 space-y-3"><div v-for="(block, index) in form.body" :key="index" class="rounded-xl border border-neutral-line p-3"><div class="flex items-center justify-between gap-3"><span class="text-xs font-semibold uppercase tracking-[0.12em] text-gold">{{ block.type === 'heading' ? `H${block.level}` : block.type }}</span><button type="button" class="text-xs text-red-700" @click="removeBlock(index)">Hapus</button></div><textarea v-if="['paragraph', 'blockquote', 'callout'].includes(block.type)" v-model="block.text" rows="3" class="mt-2 w-full rounded-lg border border-neutral-line px-3 py-2 text-sm" /><div v-else-if="block.type === 'heading'" class="mt-2 grid gap-2 sm:grid-cols-[90px_1fr]"><select v-model.number="block.level" class="rounded-lg border border-neutral-line px-2 text-sm"><option :value="2">H2</option><option :value="3">H3</option></select><input v-model="block.text" type="text" class="rounded-lg border border-neutral-line px-3 text-sm" placeholder="Subheading" /></div><div v-else-if="block.type === 'list'" class="mt-2"><select v-model="block.ordered" class="rounded-lg border border-neutral-line px-2 py-1 text-xs"><option :value="false">Bullet</option><option :value="true">Numbered</option></select><textarea :value="(block.items ?? []).join('\n')" rows="3" class="mt-2 w-full rounded-lg border border-neutral-line px-3 py-2 text-sm" @input="block.items = ($event.target as HTMLTextAreaElement).value.split('\n')" /></div><div v-else class="mt-2 grid gap-2"><MediaImageUploader v-model="block.src" label="Body image" folder="articles" /><input v-model="block.alt" type="text" class="rounded-lg border border-neutral-line px-3 py-2 text-sm" placeholder="Alt text" /><input v-model="block.caption" type="text" class="rounded-lg border border-neutral-line px-3 py-2 text-sm" placeholder="Caption (opsional)" /></div></div></div></div>

        <div class="flex flex-wrap gap-2 border-t border-neutral-line pt-4"><button type="button" class="rounded-full border border-neutral-line px-4 py-2 text-sm font-semibold hover:border-brand-green/40" @click="previewOpen = !previewOpen">{{ previewOpen ? 'Tutup Preview' : 'Preview' }}</button><button type="button" class="rounded-full bg-brand-green px-4 py-2 text-sm font-semibold text-white" @click="saveArticle('DRAFT')">Simpan Draft</button><button type="button" class="rounded-full bg-gold px-4 py-2 text-sm font-semibold text-brand-green" @click="saveArticle('PUBLISHED')">Publish</button><button v-if="editingId && form.status === 'PUBLISHED'" type="button" class="rounded-full border border-neutral-line px-4 py-2 text-sm font-semibold" @click="setStatus('DRAFT')">Return ke Draft</button><button v-if="editingId && form.status !== 'ARCHIVED'" type="button" class="rounded-full border border-red-200 px-4 py-2 text-sm font-semibold text-red-700" @click="setStatus('ARCHIVED')">Archive</button></div>
      </div></section>
    </div>

    <section v-if="previewOpen" class="mt-6 rounded-2xl border border-neutral-line bg-white p-6" aria-label="Preview artikel"><p class="text-xs font-semibold uppercase tracking-[0.16em] text-gold">Preview · {{ form.city }} · {{ form.category }}</p><h2 class="mt-3 font-heading text-3xl font-semibold">{{ form.title || 'Judul artikel' }}</h2><p class="mt-3 max-w-2xl text-base text-neutral-charcoal/65">{{ form.excerpt || 'Excerpt artikel...' }}</p><img v-if="form.heroImage" :src="form.heroImage" :alt="form.heroImageAlt" class="mt-6 max-h-[420px] w-full max-w-4xl rounded-xl object-cover" /><div class="prose prose-sm mt-8 max-w-2xl text-neutral-charcoal/80"><template v-for="(block, index) in form.body" :key="index"><p v-if="block.type === 'paragraph'">{{ block.text }}</p><h2 v-else-if="block.type === 'heading' && block.level === 2">{{ block.text }}</h2><h3 v-else-if="block.type === 'heading'">{{ block.text }}</h3><blockquote v-else-if="block.type === 'blockquote'">{{ block.text }}</blockquote><ul v-else-if="block.type === 'list' && !block.ordered"><li v-for="item in block.items" :key="item">{{ item }}</li></ul><ol v-else-if="block.type === 'list'"><li v-for="item in block.items" :key="item">{{ item }}</li></ol><aside v-else-if="block.type === 'callout'" class="border-l-2 border-gold pl-4">{{ block.text }}</aside><img v-else-if="block.type === 'image'" :src="block.src" :alt="block.alt" class="my-4 w-full rounded-xl" /></template></div></section>
  </div>
</template>
